import java.sql.*;
import java.util.*;
import java.util.stream.Collectors;

public class SqlInjectionDemo {

    // ====== 反例：字符串拼接，三类注入位置 ======

    /** 反例1：字符串值拼接 → ' OR 1=1 -- 绕过认证 */
    static ResultSet vulnerableLogin(Connection conn, String name, String pwd) throws SQLException {
        String sql = "SELECT * FROM user WHERE name = '" + name + "' AND pwd = '" + pwd + "'";
        // 输入 name="' OR 1=1 --" → WHERE name = '' OR 1=1 --' AND pwd = '...'
        return conn.createStatement().executeQuery(sql);
    }

    /** 反例2：ORDER BY 拼接 → sort="price; DROP TABLE goods --" */
    static ResultSet vulnerableSort(Connection conn, String sort, String dir) throws SQLException {
        String sql = "SELECT * FROM goods ORDER BY " + sort + " " + dir;
        // MyBatis: <select> ... order by ${sort} ${dir} </select> 同理
        return conn.createStatement().executeQuery(sql);
    }

    // ====== 正例：参数化 + 白名单 ======

    /** 正例1：值位置用 PreparedStatement 占位符 */
    static ResultSet safeLogin(Connection conn, String name, String pwd) throws SQLException {
        String sql = "SELECT * FROM user WHERE name = ? AND pwd = ?";
        PreparedStatement ps = conn.prepareStatement(sql);
        ps.setString(1, name);   // 值不再进入 SQL 解析器
        ps.setString(2, pwd);
        return ps.executeQuery();
    }

    /** 正例2：IN 子句按数组长度生成占位符 */
    static List<Map<String, Object>> safeInQuery(Connection conn, List<Long> ids) throws SQLException {
        String placeholders = ids.stream().map(i -> "?").collect(Collectors.joining(","));
        String sql = "SELECT * FROM goods WHERE id IN (" + placeholders + ")";
        PreparedStatement ps = conn.prepareStatement(sql);
        for (int i = 0; i < ids.size(); i++) ps.setLong(i + 1, ids.get(i));
        // 占位符个数在 prepare 阶段已确定，值绑定在 execute 阶段
        ResultSet rs = ps.executeQuery();
        return resultSetToList(rs);
    }

    /** 正例3：ORDER BY 走服务端白名单映射 */
    static final Map<String, String> SORT_WHITELIST = Map.of(
        "createTime", "created_at",
        "price",      "price",
        "sales",      "sold_count"
    );

    static ResultSet safeSort(Connection conn, String sortKey, String dirInput) throws SQLException {
        // 用户输入只决定 key，不直接进入 SQL
        String col = SORT_WHITELIST.getOrDefault(sortKey, "created_at");
        String dir = "asc".equalsIgnoreCase(dirInput) ? "asc" : "desc";
        // col 和 dir 都是服务端常量，拼回 SQL 安全
        String sql = "SELECT * FROM goods ORDER BY " + col + " " + dir + " LIMIT ?";
        PreparedStatement ps = conn.prepareStatement(sql);
        ps.setInt(1, 20);
        return ps.executeQuery();
    }

    private static List<Map<String, Object>> resultSetToList(ResultSet rs) throws SQLException {
        return Collections.emptyList(); // 省略实现
    }
}
